import sys

def main():
    # Read all input from standard input
    # split() handles both spaces and newlines, creating a list of token strings
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    # Create an iterator to traverse the input tokens sequentially
    iterator = iter(input_data)

    # Read N (number of contests) and R (initial rating)
    try:
        N = int(next(iterator))
        R = int(next(iterator))
    except StopIteration:
        return

    # Process each of the N contests
    for _ in range(N):
        try:
            D = int(next(iterator))
            A = int(next(iterator))
        except StopIteration:
            break

        # Determine if rating update is subject to based on division D and current rating R
        if D == 1:
            # ARC Div. 1: Rating between 1600 and 2799 inclusive
            if 1600 <= R <= 2799:
                R += A
        elif D == 2:
            # ARC Div. 2: Rating between 1200 and 2399 inclusive
            if 1200 <= R <= 2399:
                R += A

    # Print the final rating after all contests
    print(R)

if __name__ == '__main__':
    main()
